mapper.select:
SELECT o.id AS id, o.order_date AS orderDate, o.customer_name AS customerName, o.status AS status, GROUP_CONCAT(CONCAT(i.name, ' x ', CAST(oi.quantity AS UNSIGNED), i.sales_unit) SEPARATOR ', ') AS itemSummary FROM orders o JOIN order_items oi ON oi.order_id = o.id JOIN items i ON i.id = oi.item_id
o.status = #{status}
GROUP BY o.id, o.order_date, o.customer_name, o.status ORDER BY o.order_date DESC, o.id DESC

mapper.update:
UPDATE orders 
SET status = #{newStatus} 
WHERE id = #{orderId}
